import csv


def answer() -> int:
    qualifying_children = {
        ("Liwia", "Maligłówka"),
        ("Alan", "Wocial"),
    }

    with open("/app/dataset/people_accounts.csv", newline="", encoding="utf-8") as file:
        accounts = csv.DictReader(file)
        return sum(
            int(person["account_balance"])
            for person in accounts
            if (person["first_name"], person["last_name"]) in qualifying_children
        )


if __name__ == "__main__":
    import json

    with open("/app/answer.json", "w", encoding="utf-8") as file:
        json.dump(answer(), file)
